<script>
 import ClipReportArtifacts from './ClipReportArtifacts.svelte';
 import AnalysisReportMoments from './AnalysisReportMoments.svelte';
 import InboxReportSources from './InboxReportSources.svelte';
 import EvidenceConstraints from './EvidenceConstraints.svelte';
 import {untrack,tick} from 'svelte';
 import {workflowHref} from '../../lib/workflow-location.js';
 let {state:workspace,location,planIds,positions,routeEdgeIds=[],routeAvailable=true,filters={},request,onSaved,onNavigate,onRestoreView,reportRequest=0,onDirtyChange=()=>{}}=$props();
 const sectionFields=[['routes','Routes'],['partners','Partners'],['nextActions','Next actions'],['openQuestions','Open questions']];
 const normalizeSections=value=>Object.fromEntries(sectionFields.map(([key])=>[key,typeof value?.[key]==='string'?value[key]:'']));
 let sectionText=$state(normalizeSections()),baseSections=$state(normalizeSections());
 let reportsOpen=$state(false),notesOpen=$state(false),reportForm,reportTitleInput;
 $effect(()=>{if(reportRequest){reportsOpen=true;void focusReportForm();}});
 async function focusReportForm(){await tick();if(reportForm?.isConnected){reportForm.scrollIntoView({behavior:'smooth',block:'start'});reportTitleInput?.focus({preventScroll:true});}}
 function newReport(){if(dirty){error='Save or clear your working text before starting another report.';return;}onNavigate({...location,view:'report',reportId:''});reportsOpen=true;void focusReportForm();}
 $effect(()=>{if(location.view==='report')reportsOpen=true;});
 $effect(()=>{if(location.selected)notesOpen=true;});
 let groupName=$state(''),destinationName=$state(''),destinationId=$state(''),objective=$state(''),deliverables=$state(''),savedDraft=$state(null);
 let noteLabels=$state(''),noteEvidenceIds=$state([]),reportViewId=$state(''),baseViewId=$state('');
 let noteScope=$state('selection'),noteTarget=$state(null),note=$state(''),noteKind=$state('note'),viewName=$state(''),title=$state(''),thesis=$state('');
 let busy=$state(false),error=$state(''),notice=$state(''),intent=$state(null),unknown=$state(false),loadedReport=$state(''),loadedReportRevision=$state(0),baseTitle=$state(''),baseThesis=$state(''),historyIndex=$state('current');
 const report=$derived(workspace.reports.find(r=>r.id===location.reportId));
 const currentSourceRefs=$derived(report?.sourceRefs||[]);
 const currentMatchRefs=$derived((workspace.inbox?.matches||[]).filter(m=>currentSourceRefs.includes(m.sourceId)).map(m=>({id:m.id,sourceId:m.sourceId,revision:m.revision})));
 const pathNotes=$derived(workspace.annotations.filter(annotation=>annotation.target?.kind==='path'&&JSON.stringify(annotation.target.edgeIds)===JSON.stringify(routeEdgeIds)));
 const selectedNoteItem=$derived(workspace.items.find(item=>item.id===location.selected));
 const selectedNotes=$derived(workspace.annotations.filter(a=>a.targetId===location.selected));
 const viewDirty=$derived(reportViewId!==baseViewId);
 const wordingDirty=$derived(title!==baseTitle||thesis!==baseThesis||sectionFields.some(([key])=>sectionText[key]!==baseSections[key]));
 const groupMembers=$derived(planIds.filter(id=>workspace.graph.nodes.some(n=>n.id===id)));
 const dirty=$derived(Boolean(groupName.trim()||destinationName.trim()||objective.trim()||deliverables.trim()||note.trim()||noteLabels.trim()||noteEvidenceIds.length||viewName.trim()||viewDirty||wordingDirty||intent));
 $effect(()=>{onDirtyChange(dirty);});
 $effect(()=>{const id=report?.id||'',revision=report?.revision||0;untrack(()=>{if((id!==loadedReport||revision!==loadedReportRevision)&&!wordingDirty&&!viewDirty&&!intent)adoptReport(false);});});
 function adoptReport(keepWording){const pendingView=reportViewId,keepView=keepWording&&viewDirty;loadedReport=report?.id||'';loadedReportRevision=report?.revision||0;historyIndex='current';baseViewId=report?.viewId||'';reportViewId=keepView?pendingView:baseViewId;baseTitle=report?.title||'';baseThesis=report?.thesis||'';baseSections=normalizeSections(report?.sections);if(!keepWording){title=baseTitle;thesis=baseThesis;sectionText={...baseSections};}intent=null;error='';}
 function edit(){notice='';if(!unknown)intent=null;}
 function editNote(event){const value=event.currentTarget.value;if(value.trim()&&!noteTarget)noteTarget=noteScope==='route'?(routeEdgeIds.length&&routeAvailable?{kind:'path',edgeIds:[...routeEdgeIds]}:null):selectedNoteItem?{kind:'item',id:selectedNoteItem.id}:null;if(!value.trim())noteTarget=null;note=value;edit();}
 function noteTargetLabel(target){if(target?.kind==='path')return target.edgeIds.map(id=>{const edge=workspace.graph.edges.find(item=>item.id===id);const name=id=>workspace.graph.nodes.find(item=>item.id===id)?.name||'Unavailable reference';return edge?name(edge.from)+' → '+name(edge.to):'Unavailable route step';}).join(' · ');return workspace.items.find(item=>item.id===target?.id)?.name||'the original selection';}
 function saveNote(){const target=noteTarget;if(!target)return;void send('/annotations',{annotation:{...(target.kind==='path'?{target:{kind:'path',edgeIds:[...target.edgeIds]}}:{targetId:target.id}),kind:noteKind,text:note,labels:[...new Set(noteLabels.split(',').map(value=>value.trim()).filter(Boolean))],evidenceIds:[...noteEvidenceIds]}},'note');}
 async function send(path,payload,kind){
  if(busy||unknown)return;intent={path,body:{expectedRevision:workspace.revision,idempotencyKey:crypto.randomUUID(),...payload},kind};await submit();
 }
 async function submit(){
  if(!intent||busy)return;busy=true;error='';notice='';
  try{const ack=await request(intent.path,{method:'POST',body:JSON.stringify(intent.body)});const kind=intent.kind;intent=null;unknown=false;
   if(kind==='refresh'){reportViewId=ack.report.viewId||'';baseViewId=reportViewId;}if(kind==='group'){groupName='';onNavigate({...location,view:'map',focus:ack.cluster.id,selected:ack.cluster.id});}if(kind==='destination'){destinationId=ack.destination.id;destinationName='';}if(kind==='handoff'){savedDraft=ack.draft;objective='';deliverables='';}if(kind==='note'){note='';noteTarget=null;noteLabels='';noteEvidenceIds=[];}if(kind==='view')viewName='';if(kind==='report'){const pendingView=reportViewId,keepView=viewDirty;baseViewId=ack.report.viewId||'';reportViewId=keepView?pendingView:baseViewId;title=ack.report.title;thesis=ack.report.thesis;baseTitle=title;baseThesis=thesis;sectionText=normalizeSections(ack.report.sections);baseSections={...sectionText};loadedReport=ack.report.id;loadedReportRevision=ack.report.revision;onNavigate({...location,view:'report',reportId:ack.report.id});}
   notice=kind==='group'?'Working group saved':kind==='destination'?'Draft destination created':kind==='handoff'?'Draft created. Source review is still required.':kind==='refresh'?'Saved a new report snapshot':kind==='note'?'Note saved':kind==='view'?'View saved':'Report saved';try{await onSaved(ack);}catch{error='Your save succeeded, but current references could not reload. Reload to see the saved version.';}
  }catch(failure){error=failure.status===409?'The workspace changed. Your text is retained. Reload current references, then save again.':failure.message;unknown=!(Number.isInteger(failure.status)&&failure.status>=400&&failure.status<500);}
  finally{busy=false;}
 }
 async function reload(){if(busy||unknown)return;intent=null;try{await onSaved();}catch(failure){error=failure.message;}}
 function draftHref(draft){return workflowHref(window.location.href,{organizationId:draft.organizationId,brandId:draft.brandId,tab:'studio',storyId:draft.id,format:'infographic'});}
 function openView(view){if(dirty){error='Save or clear your working text before opening another view.';return;}onRestoreView(view);}
 function openReport(id){if(dirty){error='Save or clear your working text before opening a report.';return;}onNavigate({...location,view:'report',reportId:id});}
</script>
{#snippet noteReferences(saved,sources=workspace.evidence)}
 {#if saved.labels?.length}<p>Labels: {saved.labels.join(' · ')}</p>{/if}
 {#each saved.evidenceIds||[] as id(id)}{@const source=sources.find(item=>item.id===id)}{#if source}<p>{source.title}{#if source.sourceUrl} · <a href={source.sourceUrl} target="_blank" rel="noopener noreferrer">Source</a>{/if}</p>{:else}<p>Linked evidence unavailable: {id}</p>{/if}{/each}
{/snippet}
<section class="planning" aria-label="Shared planning">
 <button class="quiet" disabled={busy||unknown} onclick={reload}>Reload saved work</button>
 {#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if unknown}<p>The reply was interrupted. Retry this same save to check its outcome.</p><button disabled={busy} onclick={submit}>Retry same save</button>{:else if error}<button disabled={busy} onclick={reload}>Reload current references</button>{/if}
 <details bind:open={notesOpen}><summary>Notes <span>{selectedNotes.length+pathNotes.length}</span></summary>
 {#if location.selected}<h3>On this selection</h3><div class="notes">{#each selectedNotes as saved(saved.id)}<article><strong>{saved.kind}</strong><p>{saved.text}</p><small>Saved · revision {saved.revision}</small>{@render noteReferences(saved)}</article>{/each}</div>{/if}
 {#if routeEdgeIds.length}<h3>On your current route</h3><p>{noteTargetLabel({kind:'path',edgeIds:routeEdgeIds})}</p><div class="notes">{#each pathNotes as saved(saved.id)}<article><strong>{saved.kind}</strong><p>{saved.text}</p><small>Saved route note · revision {saved.revision}</small>{@render noteReferences(saved)}</article>{:else}<p>No notes saved for this ordered route yet.</p>{/each}</div>{/if}
 {#if location.selected||routeEdgeIds.length||noteTarget}{#if location.selected&&!selectedNoteItem}<p>This is a contextual connection. Open its referenced item to save a note, or annotate your ordered route.</p>{/if}<label>Attach note to<select bind:value={noteScope} disabled={busy||unknown||Boolean(note.trim())}><option value="selection" disabled={!selectedNoteItem}>Selected reference or relationship</option><option value="route" disabled={!routeEdgeIds.length||!routeAvailable}>Current ordered route</option></select></label><label>Note type<select bind:value={noteKind} disabled={busy||unknown}><option value="note">Note</option><option value="question">Question</option><option value="hypothesis">Hypothesis</option><option value="decision">Decision</option></select></label>{#if noteTarget}<p>Working note attached to {noteTargetLabel(noteTarget)}.</p>{/if}<label>Your note<textarea value={note} oninput={editNote} disabled={busy||unknown||(!noteTarget&&(noteScope==='route'?(!routeEdgeIds.length||!routeAvailable):!selectedNoteItem))} rows="3" maxlength="6000"></textarea></label><details><summary>Labels and evidence · optional</summary><label>Note labels, separated by commas<input bind:value={noteLabels} oninput={edit} disabled={busy||unknown||!noteTarget} placeholder="needs-check, route-idea"/></label><p>Up to 20 labels; use letters, numbers, underscores, colons or hyphens.</p><fieldset disabled={busy||unknown||!noteTarget}><legend>Link existing evidence</legend>{#each workspace.evidence as source(source.id)}<label><input type="checkbox" bind:group={noteEvidenceIds} value={source.id} onchange={edit}/>{source.title}</label>{:else}<p>Import a source reference before linking evidence.</p>{/each}</fieldset></details><button disabled={busy||unknown||!note.trim()||!noteTarget} onclick={saveNote}>Save note</button>{:else}<p>Select a reference or build a continuous route to add a shared note.</p>{/if}</details>
 <details><summary>Working groups <span>{workspace.graph.clusters.length}</span></summary><p>A working selection, not a claim that these people have agreed to collaborate.</p><div class="saved-list">{#each workspace.graph.clusters as group(group.id)}<button disabled={busy||unknown||dirty} onclick={()=>onNavigate({...location,view:'map',focus:group.id,selected:group.id})}>{group.name} · {group.nodeIds.length}</button>{/each}</div><label>Name this working group<input bind:value={groupName} oninput={edit} disabled={busy||unknown} maxlength="200"/></label><p>{groupMembers.length} shortlisted references will be included. Relationships stay separate.</p><button disabled={busy||unknown||!groupName.trim()||!groupMembers.length} onclick={()=>send('/clusters',{cluster:{name:groupName,nodeIds:groupMembers}},'group')}>Save working group</button></details>
 <details><summary>Saved views <span>{workspace.views.length}</span></summary><div class="saved-list">{#each workspace.views as view(view.id)}<button disabled={busy||unknown} onclick={()=>openView(view)}>{view.name}</button>{/each}</div><label>Name this view<input bind:value={viewName} oninput={edit} disabled={busy||unknown} maxlength="200"/></label><button disabled={busy||unknown||!viewName.trim()} onclick={()=>send('/views',{view:{name:viewName,focus:location.focus,selected:location.selected,planIds,positions,filters,routeEdgeIds}},'view')}>Save current view</button></details>
 <details bind:open={reportsOpen}><summary>Reports <span>{workspace.reports.length}</span></summary><button disabled={busy||unknown} onclick={newReport}>New report from shortlist</button><div class="saved-list">{#each workspace.reports as saved(saved.id)}<button disabled={busy||unknown} onclick={()=>openReport(saved.id)}>{saved.title}</button>{/each}</div>
 {#if location.view==='report'&&location.reportId&&!report}<p>This report is unavailable in the current organization.</p>{/if}
 {#if report}{@const snapshot=historyIndex==='current'?report:(report.history[Number(historyIndex)]||report)}<article class="report"><label>Read a report version<select bind:value={historyIndex}><option value="current">Current · revision {report.revision}</option>{#each report.history as previous,index(previous.revision)}<option value={String(index)}>Earlier · revision {previous.revision}</option>{/each}</select></label><h3>{snapshot.title}</h3><p>{snapshot.thesis}</p>{#if snapshot.view}<p>Saved graph view: <button onclick={()=>openView(snapshot.view)}>{snapshot.view.name} · revision {snapshot.viewRevision}</button></p>{/if}{#each sectionFields as [key,label](key)}{#if snapshot.sections?.[key]}<section><h4>{label}</h4><p class="section-copy">{snapshot.sections[key]}</p></section>{/if}{/each}<InboxReportSources snapshots={snapshot.sourceSnapshots||[]}/><ClipReportArtifacts snapshots={snapshot.clipSnapshots||[]} {request}/><AnalysisReportMoments snapshots={snapshot.momentSnapshots||[]}/><small>Snapshot revision {snapshot.revision} · source revision {snapshot.sourceRevision}. Changes to references do not update this report automatically.</small>{#each snapshot.findings as finding(finding.id)}<section><h4>{finding.name}</h4><p>{finding.description}</p><EvidenceConstraints record={finding.record||{}} resources={finding.resources||[]} observations={finding.observations||[]} evidence={finding.evidence||[]} />{#each finding.notes as saved(saved.id)}<blockquote>{saved.text}{@render noteReferences(saved,finding.evidence)}</blockquote>{/each}{#each finding.evidence as evidence(evidence.id)}<p>{evidence.title} · Observed {evidence.observedAt||'time unknown'}{#if evidence.sourceUrl} · <a href={evidence.sourceUrl} target="_blank" rel="noopener noreferrer">Source</a>{/if}</p>{/each}</section>{/each}{#if snapshot.annotations?.length}<details><summary>Included notes</summary>{#each snapshot.annotations as saved(saved.id)}<p>{saved.text}</p>{@render noteReferences(saved,snapshot.annotationEvidence||[])}{/each}</details>{/if}<p>{report.history.length} earlier snapshots retained.</p><button disabled={busy||unknown||(!planIds.length&&!currentSourceRefs.length)} onclick={()=>send(`/reports/${report.id}/refresh`,{expectedReportRevision:report.revision,planIds,sourceRefs:currentSourceRefs,matchRefs:currentMatchRefs,clipRefs:report.clipRefs||[],momentRefs:report.momentRefs||[],...(reportViewId?{viewId:reportViewId}:{})},'refresh')}>Refresh from current shortlist</button><button disabled={busy||unknown||dirty} onclick={()=>onNavigate({...location,view:'map',reportId:''})}>Back to map</button></article>{/if}
 {#if report&&report.id===loadedReport&&report.revision!==loadedReportRevision}<section class="version-conflict" aria-label="Newer report wording"><h3>A newer report version is saved</h3><p>Your working text is still based on revision {loadedReportRevision}. Saved revision {report.revision}: {report.title}</p><p>{report.thesis}</p>{#each sectionFields as [key,label](key)}{#if report.sections?.[key]}<h4>{label}</h4><p class="section-copy">{report.sections[key]}</p>{/if}{/each}<button disabled={busy||unknown} onclick={()=>adoptReport(false)}>Use saved wording</button><button disabled={busy||unknown} onclick={()=>adoptReport(true)}>Keep my wording on this version</button></section>{/if}
 <div bind:this={reportForm}>{#if report}<p>Wording below edits the current report. Earlier snapshots stay unchanged.</p>{/if}<label>Report title<input bind:this={reportTitleInput} bind:value={title} oninput={edit} disabled={busy||unknown} maxlength="300"/></label><label>Working thesis<textarea bind:value={thesis} oninput={edit} disabled={busy||unknown} rows="3" maxlength="12000"></textarea></label><details><summary>Plan details · optional</summary>{#each sectionFields as [key,label](key)}<label>{label}<textarea bind:value={sectionText[key]} oninput={edit} disabled={busy||unknown} rows="3" maxlength="6000"></textarea></label>{/each}</details>
 <label>Saved graph view for this snapshot<select bind:value={reportViewId} oninput={edit} disabled={busy||unknown}><option value="">No linked view</option>{#each workspace.views as view(view.id)}<option value={view.id}>{view.name}</option>{/each}</select></label>{#if report}<p>The linked view changes only when you choose Refresh from current shortlist.</p>{/if}
 <button disabled={busy||unknown||!title.trim()||(!report&&!planIds.length)} onclick={()=>send('/reports',{report:{...(report?{id:report.id,expectedReportRevision:loadedReportRevision}:{planIds,...(reportViewId?{viewId:reportViewId}:{})}),title,thesis,sections:sectionText}},'report')}>{report?'Save report wording':'Save shortlist as report'}</button><p>{report?'Saving wording preserves the findings snapshot. Refresh only when you want to capture current references.':'Choose at least one finding for your shortlist. Reports retain the evidence and notes from the time you save.'}</p></div>
 {#if report}<details class="handoff"><summary>Create a draft from this report</summary><p>Uses current saved report revision {report.revision}. Choose where this brief belongs. This creates a draft for source review; it does not publish or approve the report.</p><label>Draft destination<select value={destinationId||location.destinationBrandId} onchange={e=>{destinationId=e.currentTarget.value;edit();onNavigate({...location,destinationBrandId:destinationId});}} disabled={busy||unknown}><option value="">Choose a destination</option>{#each workspace.destinations as destination(destination.id)}<option value={destination.id}>{destination.name}</option>{/each}</select></label><details><summary>Create a separate draft destination</summary><label>Destination name<input bind:value={destinationName} oninput={edit} disabled={busy||unknown} maxlength="200"/></label><button disabled={busy||unknown||!destinationName.trim()} onclick={()=>send('/destinations',{name:destinationName},'destination')}>Create draft destination</button><p>No social account is connected by this action.</p></details><label>Objective<textarea bind:value={objective} oninput={edit} disabled={busy||unknown} rows="2" maxlength="2000"></textarea></label><label>Proposed deliverables, one per line (up to 16)<textarea bind:value={deliverables} oninput={edit} disabled={busy||unknown} rows="3"></textarea></label><button disabled={busy||unknown||!objective.trim()||!deliverables.trim()||!(destinationId||location.destinationBrandId)||wordingDirty||viewDirty||historyIndex!=='current'} onclick={()=>send(`/reports/${report.id}/handoff`,{expectedReportRevision:report.revision,destinationId:destinationId||location.destinationBrandId,objective,deliverables:deliverables.split('\n').map(value=>value.trim()).filter(Boolean)},'handoff')}>Create review-required draft</button>{#if historyIndex!=='current'}<p>Choose the current report version before creating a draft.</p>{/if}{#if wordingDirty}<p>Save or clear report wording before creating a draft from its saved version.</p>{/if}{#if viewDirty}<p>Refresh report context or clear the working view choice before creating a draft.</p><button disabled={busy||unknown} onclick={()=>{reportViewId=baseViewId;}}>Clear working view choice</button>{/if}</details>{/if}
 </details>
 {#if savedDraft}<section class="handoff-result" aria-label="Created draft"><h3>{savedDraft.title}</h3><p>Draft created with this report snapshot, your objective and proposed deliverables. Source review is required.</p><a href={draftHref(savedDraft)}>Open draft in Campaign Studio →</a></section>{/if}
 {#if dirty&&!unknown}<button class="quiet" disabled={busy} onclick={()=>{groupName='';destinationName='';objective='';deliverables='';note='';noteTarget=null;noteLabels='';noteEvidenceIds=[];reportViewId=baseViewId;viewName='';title=baseTitle;thesis=baseThesis;sectionText={...baseSections};intent=null;error='';}}>Clear working text</button>{/if}
</section>
<style>
.planning{padding:16px 20px;border-top:1px solid #dedfd8;background:#fcfcf9;font-size:12px}.planning>details{padding:10px 0;border-bottom:1px solid #e4e6df}.planning summary{cursor:pointer;font-weight:650}.planning summary span{font-weight:400;color:#69765f;margin-left:6px}.planning label{display:block;margin:12px 0 6px}.planning textarea,.planning input,.planning select{display:block;width:100%;margin-top:5px;font:inherit}.planning button{margin:8px 8px 0 0}.planning p{line-height:1.65}.notes article,.report section{border-left:2px solid #bdcbb4;padding-left:12px;margin:12px 0}.saved-list{display:flex;gap:6px;flex-wrap:wrap}.report{padding-top:12px}.report h3{font-size:20px}.report small{color:#69765f}.planning blockquote{margin:8px 0;color:#596a51}.quiet{background:transparent}.section-copy{white-space:pre-wrap}
</style>
